import React, { useState, useEffect, useMemo } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useOffline } from '../../contexts/OfflineContext';
import { useDonors } from '../../contexts/DonorContext';

const Navbar = () => {
    const [isOpen, setIsOpen] = useState(false);
    const { isOffline } = useOffline();
    const { agentAssignments, loading, checkEmptyAgents } = useDonors();
    const location = useLocation();
    const navigate = useNavigate();

    // Check for completed agents on initial load and navigation
    useEffect(() => {
        checkEmptyAgents();
    }, [location.pathname, checkEmptyAgents]);

    // Use useMemo to stabilize agent links and prevent unnecessary re-renders
    const agentLinks = useMemo(() => {
        if (!agentAssignments || loading) return [];

        return agentAssignments
            .filter(agent => agent?.total_donations !== agent?.completed_donations) // Filter out agents with only completed tasks
            .map(agent => ({
                id: agent.id,
                name: agent.name || agent.agent_name,
                path: `/agent/${agent.id}`
            }));
    }, [agentAssignments, loading]);

    // Redirect to dashboard if current agent page no longer exists
    useEffect(() => {
        if (location.pathname.startsWith('/agent/') && agentLinks.length > 0) {
            const agentId = location.pathname.split('/')[2];
            if (!agentLinks.find(link => link.id.toString() === agentId)) {
                navigate('/');
            }
        }
    }, [location.pathname, agentLinks, navigate]);

    // Close mobile menu when route changes
    useEffect(() => {
        setIsOpen(false);
    }, [location.pathname]);

    const isActive = (path) => location.pathname === path;

    return (
        <nav className="bg-green-700 text-white shadow-lg">
            <div className="container mx-auto px-4">
                <div className="flex justify-between items-center h-16">
                    <div className="flex-shrink-0 flex items-center">
                        <Link to="/" className="font-bold text-xl">Al-Insan Foundation</Link>
                        {isOffline && (
                            <span className="ml-3 px-2 py-1 text-xs font-semibold bg-red-600 rounded-full">
                                Offline
                            </span>
                        )}
                    </div>

                    {/* Desktop menu */}
                    <div className="hidden md:block">
                        <div className="ml-10 flex items-center space-x-4">
                            <Link
                                to="/"
                                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${isActive('/') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            >
                                Dashboard
                            </Link>
                            <Link
                                to="/register"
                                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${isActive('/register') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            >
                                Register Donor
                            </Link>
                            <Link
                                to="/donors"
                                className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${isActive('/donors') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                            >
                                Donor List
                            </Link>

                            {/* Dynamic Agent Tabs - Stable rendering with key by ID */}
                            {agentLinks.map((agent) => (
                                <Link
                                    key={`desktop-${agent.id}`}
                                    to={agent.path}
                                    className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${isActive(agent.path) ? 'bg-green-800' : 'hover:bg-green-600'}`}
                                >
                                    {agent.name}
                                </Link>
                            ))}
                        </div>
                    </div>

                    {/* Mobile menu button */}
                    <div className="md:hidden flex items-center">
                        <button
                            onClick={() => setIsOpen(!isOpen)}
                            className="inline-flex items-center justify-center p-2 rounded-md text-white hover:bg-green-600 focus:outline-none"
                            aria-expanded={isOpen}
                        >
                            <span className="sr-only">{isOpen ? 'Close menu' : 'Open menu'}</span>
                            <svg
                                className="h-6 w-6"
                                xmlns="http://www.w3.org/2000/svg"
                                fill="none"
                                viewBox="0 0 24 24"
                                stroke="currentColor"
                                aria-hidden="true"
                            >
                                {isOpen ? (
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                                ) : (
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                                )}
                            </svg>
                        </button>
                    </div>
                </div>
            </div>

            {/* Mobile menu - Added transition for smooth opening/closing */}
            <div
                className={`md:hidden transition-all duration-300 ease-in-out ${isOpen ? 'max-h-screen opacity-100' : 'max-h-0 opacity-0 overflow-hidden'}`}
            >
                <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
                    <Link
                        to="/"
                        className={`block px-3 py-2 rounded-md text-base font-medium ${isActive('/') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                    >
                        Dashboard
                    </Link>
                    <Link
                        to="/register"
                        className={`block px-3 py-2 rounded-md text-base font-medium ${isActive('/register') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                    >
                        Register Donor
                    </Link>
                    <Link
                        to="/donors"
                        className={`block px-3 py-2 rounded-md text-base font-medium ${isActive('/donors') ? 'bg-green-800' : 'hover:bg-green-600'}`}
                    >
                        Donor List
                    </Link>

                    {/* Dynamic Agent Tabs - Mobile version */}
                    {agentLinks.map((agent) => (
                        <Link
                            key={`mobile-${agent.id}`}
                            to={agent.path}
                            className={`block px-3 py-2 rounded-md text-base font-medium ${isActive(agent.path) ? 'bg-green-800' : 'hover:bg-green-600'}`}
                        >
                            {agent.name}
                        </Link>
                    ))}
                </div>
            </div>
        </nav>
    );
};

export default React.memo(Navbar);
